# Translates Unity's Metal shader programs (MSL generated by HLSLcc) to
# GLSL ES 3.00, one vertex + one fragment program into a single Unity GLES3
# source ("#ifdef VERTEX ... #endif #ifdef FRAGMENT ... #endif").
#
# Parsing reuses upstream GoSRecomp's msl2hlsl.parse. As upstream does for
# HLSL, the body of xlatMtlMain is kept and only rewritten: Metal's in/out
# structs stay as local structs, filled from / copied to the GLSL stage
# globals. Varyings link by name (vs_<user name>), attributes by Unity's GL
# names (in_POSITION0, in_TEXCOORD0, ...).
import re

from msl2hlsl import Unsupported, parse, split_args, split_type  # upstream


def rewrite_calls(text, name, fn):
    """Replaces every call matching `name` (regex ending at the opening
    parenthesis) with fn(match, args); nested calls in args are rewritten too."""
    out, pos = [], 0
    pat = re.compile(name)
    while True:
        m = pat.search(text, pos)
        if not m:
            out.append(text[pos:])
            return "".join(out)
        i = m.end()
        depth, j = 1, i
        while depth:
            depth += {"(": 1, ")": -1}.get(text[j], 0)
            j += 1
        args = [rewrite_calls(a, name, fn) for a in split_args(text[i:j - 1])]
        out.append(text[pos:m.start()])
        out.append(fn(m, args))
        pos = j

GLSL_VEC = {"float": "vec", "int": "ivec", "uint": "uvec", "bool": "bvec"}
SAMPLER = {
    "texture2d": "sampler2D", "texture3d": "sampler3D", "texturecube": "samplerCube",
    "texture2d_array": "sampler2DArray", "depth2d": "sampler2D", "depth2d_array": "sampler2DArray",
    "depthcube": "samplerCube",
}
SHADOW = {"depth2d": "sampler2DShadow", "depth2d_array": "sampler2DArrayShadow", "depthcube": "samplerCubeShadow"}
DIM = {"texture2d": 2, "depth2d": 2, "texture3d": 3, "texturecube": 4, "depthcube": 4,
       "texture2d_array": 5, "depth2d_array": 5}  # Unity TextureDimension: 2 = 2D, 3 = 3D, 4 = Cube, 5 = 2DArray

PREAMBLE = """#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif"""

HELPERS = """#define gosr_fma(a, b, c) ((a) * (b) + (c))
"""


def glsl_type(base, n):
    if n == 1:
        return base
    return f"{GLSL_VEC[base]}{n}"


def gtype(msl_type):
    base, n = split_type(msl_type)
    return glsl_type(base, n)


def precision_of(msl_type):
    return "mediump " if msl_type.startswith("half") else "highp "


# ------------------------------------------------------------ type tables

def var_types(prog, body):
    """name -> (base, n) for locals, struct members are looked up separately."""
    t = {}
    for m in re.finditer(r"\b(float|half|int|uint|bool|short|ushort)([1-4]?)\s+(\w+)\s*(?:\[\s*\d+\s*\])?\s*;", body):
        base, n = split_type(m.group(1) + m.group(2))
        t[m.group(3)] = (base, n)
    for sname, members in prog.structs.items():
        for mb in members:
            try:
                t[mb.name] = split_type(mb.type)
            except Unsupported:
                pass
    return t


def base_of(expr, types):
    """Best guess of an expression's scalar base type (float/int/uint/bool)."""
    e = expr.strip()
    m = re.match(r"\(*\s*(float|half|int|uint|bool|vec|ivec|uvec|bvec)\d?\s*\(", e)
    if m:
        return {"half": "float", "vec": "float", "ivec": "int", "uvec": "uint", "bvec": "bool"}.get(m.group(1), m.group(1))
    m = re.match(r"\(*\s*(floatBitsToUint|floatBitsToInt|uintBitsToFloat|intBitsToFloat)\(", e)
    if m:
        return {"floatBitsToUint": "uint", "floatBitsToInt": "int"}.get(m.group(1), "float")
    for ident in re.findall(r"\b([A-Za-z_]\w*)\b", e):
        if ident in types:
            return types[ident][0]
        if ident.startswith("u_xlati"):
            return "int"
        if ident.startswith("u_xlatu"):
            return "uint"
        if ident.startswith("u_xlatb"):
            return "bool"
        if ident.startswith("u_xlat"):
            return "float"
    if re.fullmatch(r"-?\d+u", e):
        return "uint"
    if re.fullmatch(r"-?\d+", e):
        return "int"
    return "float"


def width_of(expr, types):
    e = expr.strip()
    m = re.search(r"\.([xyzw]{1,4}|[rgba]{1,4})\s*$", e)
    if m and not re.search(r"\)\s*$", e[:m.start()]) or (m and e.count("(") == 0):
        return len(m.group(1))
    m = re.match(r"\(*\s*(?:float|half|int|uint|bool|vec|ivec|uvec|bvec)([2-4])\s*\(", e)
    if m:
        return int(m.group(1))
    m = re.fullmatch(r"\(*\s*(\w+)\s*\)*", e)
    if m and m.group(1) in types:
        return types[m.group(1)][1]
    if m:
        return 1
    return 0  # unknown


# ------------------------------------------------------------ body rewriting

CMP_FN = {"<": "lessThan", "<=": "lessThanEqual", ">": "greaterThan", ">=": "greaterThanEqual",
          "==": "equal", "!=": "notEqual"}


def split_top_cmp(expr):
    """'a < b' at paren depth 0 -> (a, op, b)."""
    depth = 0
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch in "([":
            depth += 1
        elif ch in ")]":
            depth -= 1
        elif depth == 0 and ch in "<>=!":
            two = expr[i:i + 2]
            if two in ("<=", ">=", "==", "!="):
                return expr[:i], two, expr[i + 2:]
            if ch in "<>" and expr[i + 1:i + 2] not in "<>" and expr[i - 1:i] not in "<>":
                return expr[:i], ch, expr[i + 1:]
        i += 1
    return None


def vector_compare(expr, types, width_hint):
    """Rewrites a vector comparison 'a OP b' to lessThan(...) etc."""
    inner = expr.strip()
    while inner.startswith("(") and inner.endswith(")") and balanced(inner[1:-1]):
        inner = inner[1:-1].strip()
    parts = split_top_cmp(inner)
    if not parts:
        return None
    a, op, b = parts
    w = max(width_of(a, types), width_of(b, types), width_hint)
    if w < 2:
        return None
    return f"{CMP_FN[op]}({a.strip()}, {b.strip()})"


def balanced(s):
    d = 0
    for ch in s:
        d += {"(": 1, ")": -1}.get(ch, 0)
        if d < 0:
            return False
    return d == 0


def rewrite_texture(m, args, tex_kinds, compare_tex):
    tex, method = m.group(1), m.group(2)
    kind = tex_kinds.get(tex, "texture2d")
    if method in ("get_width", "get_height", "get_depth"):
        lod = args[0] if args else "0"
        c = {"get_width": "x", "get_height": "y", "get_depth": "z"}[method]
        return f"uint(textureSize({tex}, int({lod})).{c})"
    extra, plain = {}, []
    for a in args:
        mm = re.fullmatch(r"(level|bias|gradient2d|gradient3d|gradientcube|min_lod_clamp)\((.*)\)", a.strip(), re.S)
        if mm:
            extra[mm.group(1)] = split_args(mm.group(2))
        else:
            plain.append(a)
    if method == "read":
        coord = plain[0]
        lod = plain[1] if len(plain) > 1 else "0"
        if kind.endswith("_array"):
            return f"texelFetch({tex}, ivec3(ivec2({coord}), int({plain[1]})), int({plain[2] if len(plain) > 2 else '0'}))"
        n = 3 if kind == "texture3d" else 2
        return f"texelFetch({tex}, ivec{n}({coord}), int({lod}))"
    coord = plain[1]
    rest = plain[2:]
    if kind.endswith("_array"):
        coord = f"vec3({coord}, float({rest[0]}))" if "cube" not in kind else f"vec4({coord}, float({rest[0]}))"
        rest = rest[1:]
    if method == "sample_compare":
        ref = rest[0]
        offs = rest[1:]
        n = {"depth2d": 3, "depth2d_array": 4, "depthcube": 4}.get(kind, 3)
        c = f"vec{n}({coord}, {ref})" if n < 4 or kind == "depth2d_array" else f"vec4({coord}, {ref})"
        if offs:
            return f"textureOffset({tex}, {c}, {offs[0]})"
        return f"texture({tex}, {c})"
    if "level" in extra:
        lv = extra["level"][0]
        if rest:
            return f"textureLodOffset({tex}, {coord}, {lv}, {rest[0]})"
        return f"textureLod({tex}, {coord}, {lv})"
    if "bias" in extra:
        return f"texture({tex}, {coord}, {extra['bias'][0]})"
    for g in ("gradient2d", "gradient3d", "gradientcube"):
        if g in extra:
            return f"textureGrad({tex}, {coord}, {', '.join(extra[g])})"
    if rest:
        return f"textureOffset({tex}, {coord}, {rest[0]})"
    expr = f"texture({tex}, {coord})"
    if kind.startswith("depth"):
        expr += ".x"  # Metal depth textures sample to a scalar
    return expr


def rewrite_as_type(m, args, types):
    dst = m.group(1)
    n = m.group(2) or ""
    src = base_of(args[0], types)
    a = args[0]
    if dst == src:
        return f"({a})"
    fn = {("float", "uint"): "floatBitsToUint", ("float", "int"): "floatBitsToInt",
          ("uint", "float"): "uintBitsToFloat", ("int", "float"): "intBitsToFloat"}.get((src, dst))
    if fn:
        return f"{fn}({a})"
    ctor = glsl_type(dst, int(n) if n else 1)
    return f"{ctor}({a})"


def rewrite_select(m, args, types):
    a, b, c = args
    if width_of(c, types) >= 2 or re.match(r"\s*bool[2-4]\(", c):
        return f"gosr_select({a}, {b}, {c})"
    return f"(({c}) ? ({b}) : ({a}))"


def rewrite_body(body, cbuffer_names, tex_kinds, types):
    b = body
    for cb in cbuffer_names:
        b = re.sub(rf"\b{cb}\.", "", b)
    b = re.sub(r"\b(?:precise|fast)::", "", b)
    b = re.sub(r"\bmetal::", "", b)
    b = re.sub(r"\bfma\(", "gosr_fma(", b)
    b = re.sub(r"\brint\(", "roundEven(", b)
    b = re.sub(r"\bdfdx\(", "dFdx(", b)
    b = re.sub(r"\bdfdy\(", "dFdy(", b)
    b = re.sub(r"\brsqrt\(", "inversesqrt(", b)
    b = re.sub(r"\bpowr\(", "pow(", b)
    b = re.sub(r"\bdiscard_fragment\(\)", "discard", b)
    b = re.sub(r"\bsaturate\(", "gosr_saturate(", b)
    if re.search(r"\b(thread|device|threadgroup)\b", b):
        raise Unsupported("address space qualifier in body")
    inline = re.findall(r"constexpr\s+sampler\s+(\w+)\s*\(.*?\);", b, re.S)
    b = re.sub(r"constexpr\s+sampler\s+(\w+)\s*\(.*?\);", "", b, flags=re.S)
    compare_tex = set(re.findall(r"\b(\w+)\.sample_compare\(", b))
    # calls whose meaning depends on argument types, before type names change
    b = rewrite_calls(b, r"\bas_type<(float|uint|int|half)([2-4]?)>\(", lambda m, a: rewrite_as_type(m, a, types))
    b = rewrite_calls(b, r"\bselect\(", lambda m, a: rewrite_select(m, a, types))
    b = rewrite_calls(b, r"\b(\w+)\.(sample_compare|sample|read|get_width|get_height|get_depth)\(",
                      lambda m, a: rewrite_texture(m, a, tex_kinds, compare_tex))
    # vector comparisons: boolN(a < b) and  bvecLHS = (a < b);
    b = rewrite_calls(b, r"\bbool([2-4])\(", lambda m, a: vector_compare(a[0], types, int(m.group(1))) or f"bvec{m.group(1)}({a[0]})")

    def ctor_cmp(m, a):  # uint2(a >= b) and friends
        n = int(m.group(2))
        if len(a) == 1:
            r = vector_compare(a[0], types, n)
            if r:
                return f"{m.group(1)}{n}({r})"
        return f"{m.group(1)}{n}({', '.join(a)})"
    b = rewrite_calls(b, r"\b(float|half|int|uint)([2-4])\(", ctor_cmp)

    def stmt_cmp(m):
        lhs, rhs = m.group(1), m.group(2)
        w = width_of(lhs, types)
        if w >= 2 and base_of(lhs, types) == "bool":
            r = vector_compare(rhs, types, w)
            if r:
                return f"{lhs} = {r};"
        return m.group(0)
    b = re.sub(r"(\b[\w.\[\]]+)\s*=\s*(\([^;]*\))\s*;", stmt_cmp, b)
    # vector logic on bool vectors: !bvec -> not(bvec)
    b = re.sub(r"!\s*\((u_xlatb\d+\.[xyzw]{2,4})\)", r"not(\1)", b)
    # types and literals
    b = re.sub(r"\bvec<(\w+),\s*(\d)>", r"\1\2", b)
    b = re.sub(r"\b(float|half)([2-4])x([2-4])\b", lambda m: f"mat{m.group(2)}x{m.group(3)}" if m.group(2) != m.group(3) else f"mat{m.group(2)}", b)
    b = re.sub(r"\b(float|half|int|uint|bool|short|ushort)([2-4])\b",
               lambda m: glsl_type({"half": "float", "short": "int", "ushort": "uint"}.get(m.group(1), m.group(1)), int(m.group(2))), b)
    b = re.sub(r"\bhalf\b", "float", b)
    b = re.sub(r"\bshort\b", "int", b)
    b = re.sub(r"\bushort\b", "uint", b)
    b = re.sub(r"(\d\.?\d*(?:[eE][-+]?\d+)?)[hf]\b", r"\1", b)
    return b, inline, compare_tex


# ------------------------------------------------------------ emit

def stage_globals(prog):
    """Uniforms, textures and system inputs of one stage."""
    uniforms, textures, cb_names, tex_kinds, sysvals = [], [], [], {}, []
    for t, name, attr in prog.params:
        if t.endswith("&") and t.startswith("constant "):
            st = t[len("constant "):-1].strip()
            cb_names.append(name)
            for mb in prog.structs[st]:
                uniforms.append((mb.name, mb.type, mb.array))
        elif t.endswith("*"):
            raise Unsupported("buffer pointer parameter (instancing / structured buffer)")
        elif t == "sampler":
            pass
        elif attr and attr.startswith("texture"):
            mm = re.fullmatch(r"(\w+)<\s*(\w+)\s*,.*>", t)
            kind = mm.group(1)
            if kind not in SAMPLER:
                raise Unsupported(f"texture type {kind}")
            tex_kinds[name] = kind
            treg = int(re.search(r"texture\s*\((\d+)\)", attr).group(1))
            textures.append((name, treg, kind, mm.group(2)))
        elif attr == "stage_in":
            pass
        elif attr in ("position", "instance_id", "base_instance", "front_facing", "vertex_id"):
            sysvals.append((t, name, attr))
        else:
            raise Unsupported(f"parameter {t} {name} [[{attr}]]")
    return uniforms, textures, cb_names, tex_kinds, sysvals


def emit_stage(prog, varyings, all_uniforms, all_textures):
    uniforms, textures, cb_names, tex_kinds, sysvals = stage_globals(prog)
    out = []
    if prog.stage == "fragment":
        out.append("precision highp float;\nprecision highp int;")
    out.append("precision highp sampler3D;\nprecision highp sampler2DArray;\nprecision highp samplerCube;\n"
               "precision highp sampler2DShadow;\nprecision highp sampler2DArrayShadow;\nprecision highp samplerCubeShadow;")
    out.append(PREAMBLE)
    out.append(HELPERS)
    types = var_types(prog, prog.body)
    for cb in cb_names:
        pass
    body, inline, compare_tex = rewrite_body(prog.body, cb_names, tex_kinds, types)
    # uniforms of both stages (identical declarations link)
    for name, mtype, arr in all_uniforms:
        base, n = split_type(mtype)
        a = f"[{arr}]" if arr else ""
        out.append(f"uniform \t{precision_of(mtype)}{glsl_type(base, n)} {name}{a};")
    for name, unit, kind, elem in all_textures:
        st = SHADOW[kind] if (name in compare_tex and kind in SHADOW) else SAMPLER[kind]
        if elem in ("uint", "ushort"):
            st = "u" + st
        elif elem in ("int", "short"):
            st = "i" + st
        out.append(f"UNITY_LOCATION({unit}) uniform highp {st} {name};")
    out.extend(re.sub(r"static const", "const", g).replace("float", "float") for g in [])
    for g in prog.globals:  # 'static const T n[k] = {...};' (HLSL form from upstream parse)
        mm = re.fullmatch(r"static const (\w+) (\w+)\[(\d+)\] = \{(.*)\};", g, re.S)
        if not mm:
            raise Unsupported("global constant")
        t = gtype(mm.group(1))
        init = re.sub(r"\b(float|half|int|uint|bool)([2-4])\b",
                      lambda k: glsl_type({"half": "float"}.get(k.group(1), k.group(1)), int(k.group(2))), mm.group(4))
        out.append(f"const {t} {mm.group(2)}[{mm.group(3)}] = {t}[{mm.group(3)}]({init.strip()});")

    # Metal structs as local GLSL structs (constant buffer structs excluded)
    cb_structs = {t[len('constant '):-1].strip() for t, n, a in prog.params if t.startswith("constant ")}
    for sname, members in prog.structs.items():
        if sname in cb_structs:
            continue
        out.append(f"struct {sname} {{")
        for mb in members:
            a = f"[{mb.array}]" if mb.array else ""
            out.append(f"    {gtype(mb.type)} {mb.name}{a};")
        out.append("};")

    stage_in = next(((t, n) for t, n, a in prog.params if a == "stage_in"), None)
    pre, post = [], []
    if prog.stage == "vertex":
        if stage_in:
            pre.append(f"    {stage_in[0]} {stage_in[1]};")
            for mb in prog.structs[stage_in[0]]:
                out.append(f"in {precision_of(mb.type)}{gtype(mb.type)} in_{mb.name};")
                pre.append(f"    {stage_in[1]}.{mb.name} = in_{mb.name};")
        for sem, (base, n, interp) in varyings:
            q = "flat " if interp == "flat" else ""
            out.append(f"{q}out highp {glsl_type(base, n)} vs_{sem};")
        vout = prog.structs[prog.ret_type]
        for mb in vout:
            if mb.attr == "position":
                post.append(f"    gl_Position = output.{mb.name};")
            elif mb.attr == "point_size":
                post.append(f"    gl_PointSize = output.{mb.name};")
            elif mb.attr and mb.attr.startswith("user("):
                sem = mb.attr[5:-1].strip()
                n = split_type(mb.type)[1]
                post.append(f"    vs_{sem}.{'xyzw'[:n]} = output.{mb.name};" if dict(varyings)[sem][1] > n
                            else f"    vs_{sem} = output.{mb.name};")
            elif mb.attr and mb.attr.startswith("clip_distance"):
                pass
            else:
                raise Unsupported(f"vertex output [[{mb.attr}]]")
    else:
        for sem, (base, n, interp) in varyings:
            q = "flat " if interp == "flat" else ""
            out.append(f"{q}in highp {glsl_type(base, n)} vs_{sem};")
        if stage_in:
            pre.append(f"    {stage_in[0]} {stage_in[1]};")
            for mb in prog.structs[stage_in[0]]:
                if mb.attr == "position":
                    pre.append(f"    {stage_in[1]}.{mb.name} = gl_FragCoord;")
                elif mb.attr == "front_facing":
                    pre.append(f"    {stage_in[1]}.{mb.name} = gl_FrontFacing;")
                elif mb.attr and mb.attr.startswith("user("):
                    sem = mb.attr[5:-1].strip()
                    n = split_type(mb.type)[1]
                    pre.append(f"    {stage_in[1]}.{mb.name} = vs_{sem}" + (f".{'xyzw'[:n]};" if dict(varyings)[sem][1] > n else ";"))
                else:
                    raise Unsupported(f"fragment input [[{mb.attr}]]")
        fout = prog.structs[prog.ret_type]
        for mb in fout:
            mm = re.match(r"color\((?:xlt_remap_o\[)?(\d+)", mb.attr or "")
            if mm:
                out.append(f"layout(location = {mm.group(1)}) out {precision_of(mb.type)}{gtype(mb.type)} SV_Target{mm.group(1)};")
                post.append(f"    SV_Target{mm.group(1)} = output.{mb.name};")
            elif (mb.attr or "").startswith("depth"):
                post.append(f"    gl_FragDepth = output.{mb.name};")
            else:
                raise Unsupported(f"fragment output [[{mb.attr}]]")
    for t, name, attr in sysvals:
        if attr == "position":
            pre.append(f"    vec4 {name} = gl_FragCoord;")
        elif attr == "front_facing":
            pre.append(f"    bool {name} = gl_FrontFacing;")
        elif attr == "vertex_id":
            pre.append(f"    uint {name} = uint(gl_VertexID);")
        elif attr == "instance_id":
            pre.append(f"    uint {name} = uint(gl_InstanceID);")
        elif attr == "base_instance":
            pre.append(f"    uint {name} = 0u;")
    out.append(SELECT_HELPERS)
    out.append(f"void gosr_main({prog.ret_type} output_unused_dummy);" if False else "")
    out.append("void main()\n{")
    out.extend(pre)
    body = re.sub(r"\breturn\s+output\s*;", "GOSR_RETURN;", body)
    out.append(body)
    out.append("    GOSR_RETURN;\n}")
    src = "\n".join(out)
    src = src.replace("GOSR_RETURN;", "{\n" + "\n".join(post) + "\n    return;\n    }")
    src = re.sub(r"\b(input|output)\b", r"gosr_\1", src)  # reserved words in GLSL
    # 'return;' followed by our epilogue: the final one is unreachable but legal
    return src, inline


SELECT_HELPERS = "\n".join(
    [f"float gosr_saturate(float x) {{ return clamp(x, 0.0, 1.0); }}"] +
    [f"vec{n} gosr_saturate(vec{n} x) {{ return clamp(x, 0.0, 1.0); }}" for n in (2, 3, 4)] +
    [f"{t}{n} gosr_select({t}{n} a, {t}{n} b, bvec{n} c) {{ {t}{n} r; " + " ".join(f"r.{c} = c.{c} ? b.{c} : a.{c};" for c in "xyzw"[:n]) + " return r; }"
     for t in ("vec", "ivec", "uvec", "bvec") for n in (2, 3, 4)])


def varyings_of(prog):
    if prog.stage == "vertex":
        struct = prog.structs[prog.ret_type]
    else:
        struct = next((prog.structs[t] for t, n, a in prog.params if a == "stage_in"), [])
    out = {}
    for mb in struct:
        if mb.attr and mb.attr.startswith("user("):
            sem = mb.attr[5:-1].strip()
            base, n = split_type(mb.type)
            out[sem] = (base, n, "flat" if base in ("int", "uint") or getattr(mb, "flat", False) else "smooth")
    return out


def union_varyings(vs, fs):
    union = {}
    for p in (vs, fs):
        for sem, (base, n, interp) in varyings_of(p).items():
            if sem in union:
                b0, n0, i0 = union[sem]
                if b0 != base:
                    raise Unsupported(f"varying {sem} changes type between stages")
                union[sem] = (base, max(n, n0), i0)
            else:
                union[sem] = (base, n, interp)
    return sorted(union.items())


def translate_pair(vs_msl, fs_msl):
    """Returns (glsl source, uniforms [(name, msl type, array)], textures [(name, unit, kind)])."""
    vs, fs = parse(vs_msl), parse(fs_msl)
    if vs.stage != "vertex" or fs.stage != "fragment":
        raise Unsupported("stage mismatch")
    varyings = union_varyings(vs, fs)
    uniforms, seen = [], {}
    textures, tseen = [], {}
    for p in (vs, fs):
        u, t, _, _, _ = stage_globals(p)
        for name, mtype, arr in u:
            if name in seen:
                if seen[name] != (mtype, arr):
                    raise Unsupported(f"uniform {name} differs between stages")
                continue
            seen[name] = (mtype, arr)
            uniforms.append((name, mtype, arr))
        for name, unit, kind, elem in t:
            if name in tseen:
                continue
            tseen[name] = unit
            textures.append((name, unit, kind, elem))
    # GL texture units: one per texture name, in Metal slot order
    units = {}
    for name, unit, kind, elem in sorted(textures, key=lambda x: x[1]):
        units[name] = len(units)
    textures = [(name, units[name], kind, elem) for name, unit, kind, elem in textures]
    vsrc, _ = emit_stage(vs, varyings, uniforms, [t for t in textures if t[0] in {x[0] for x in stage_globals(vs)[1]}])
    fsrc, _ = emit_stage(fs, varyings, uniforms, [t for t in textures if t[0] in {x[0] for x in stage_globals(fs)[1]}])
    src = f"#ifdef VERTEX\n#version 300 es\n\n{vsrc}\n#endif\n#ifdef FRAGMENT\n#version 300 es\n\n{fsrc}\n#endif\n"
    return src, uniforms, textures
